import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long baud = in.nextLong();
        int m = in.nextInt();
        int bits = 0;
        while (m > 1) {
            m /= 2;
            bits++;
        }
        System.out.println(baud);
    }
}

